import { Switch as BaseSwitch } from '@base-ui/react/switch';
import type { ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { switchVariants, type SwitchVariantProps } from './switch.variants';

export interface SwitchProps extends Omit<BaseSwitch.Root.Props, 'className'>, SwitchVariantProps {
  className?: string;
  ref?: Ref<HTMLButtonElement>;
  /** Visible label. Without it, pass `aria-label` or wrap in a Field. */
  label?: ReactNode;
  /** Marks the switch invalid; pair with a FieldError or description. */
  invalid?: boolean;
  /** Label placement relative to the track. */
  labelPosition?: 'start' | 'end';
}

/** On/off setting. Controlled with `checked` + `onCheckedChange`, or uncontrolled with `defaultChecked`. */
export function Switch({ size, label, labelPosition = 'end', className, invalid, ...props }: SwitchProps) {
  const s = switchVariants({ size });
  const control = (
    <BaseSwitch.Root
      className={cn(s.root(), !label && className)}
      {...props}
      {...(invalid ? { 'data-invalid': true } : {})}
      aria-invalid={props['aria-invalid'] ?? (invalid || undefined)}
    >
      <BaseSwitch.Thumb className={s.thumb()} />
    </BaseSwitch.Root>
  );
  if (!label) return control;
  return (
    <label className={cn(s.label(), props.disabled && 'opacity-70', className)}>
      {labelPosition === 'start' && label}
      {control}
      {labelPosition === 'end' && label}
    </label>
  );
}

export { Switch, type SwitchProps } from './Switch';
export { switchVariants } from './switch.variants';
export { doc as switchDoc } from './Switch.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const switchVariants = tv({
  slots: {
    root: [
      'relative inline-flex shrink-0 cursor-interactive items-center rounded-full bg-secondary transition-colors',
      'data-checked:bg-primary',
      'data-invalid:ring-1 data-invalid:ring-destructive/70 aria-invalid:ring-1 aria-invalid:ring-destructive/70',
      'forced-colors:bg-[Canvas] forced-colors:outline forced-colors:-outline-offset-1 forced-colors:outline-[ButtonBorder] forced-colors:data-checked:bg-[Highlight] forced-colors:data-disabled:outline-[GrayText]',
      'focus-ring',
      'data-disabled:cursor-disabled data-disabled:opacity-50',
    ],
    thumb:
      'pointer-events-none ms-[2px] grid place-items-center rounded-full bg-background shadow-sm transition-transform motion-reduce:transition-none forced-colors:bg-[ButtonText] forced-colors:data-checked:bg-[HighlightText] forced-colors:data-disabled:bg-[GrayText]',
    label: 'inline-flex items-center gap-2.5 text-[13px] text-foreground',
  },
  variants: {
    size: {
      sm: {
        root: 'h-[18px] w-8',
        thumb: 'size-3.5 data-checked:translate-x-[14px] rtl:data-checked:-translate-x-[14px]',
      },
      md: {
        root: 'h-[22px] w-[40px]',
        thumb: 'size-[18px] data-checked:translate-x-[18px] rtl:data-checked:-translate-x-[18px]',
      },
      lg: {
        root: 'h-[26px] w-[46px]',
        thumb: 'size-[22px] data-checked:translate-x-[20px] rtl:data-checked:-translate-x-[20px]',
      },
    },
  },
  defaultVariants: { size: 'md' },
});

export type SwitchVariantProps = VariantProps<typeof switchVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Switch',
  group: 'Forms',
  status: 'stable',
  description:
    'On/off setting that applies immediately. Three sizes, optional inline label, works inside Field and Form. An explicit aria-label takes precedence over the visible label; keep both consistent for WCAG 2.5.3 (label in name). The optional invalid prop exposes aria-invalid and a destructive 1px track ring, checked or unchecked. Invalid Field also supplies this state. Pair invalid with a FieldError or description explaining how to correct the value; colour alone is insufficient.',
  // Invalid state is demonstrated in SwitchInvalid.
  primitive: '@base-ui/react/switch',
  pattern: 'switch',
  keyboard: [
    ['Space', 'Toggles the switch'],
    ['Enter', 'Toggles the switch'],
    ['Tab', 'Moves focus to and from the switch'],
  ],
  dataAttributes: [
    ['data-checked', 'root', 'The control is checked.'],
    ['data-disabled', 'root', 'The control cannot be changed or activated.'],
    ['data-checked', 'thumb', 'The control is checked.'],
    ['data-disabled', 'thumb', 'The control cannot be changed or activated.'],
  ],
  tokens: ['destructive', 'primary', 'secondary', 'background', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** JSX skeleton showing the public compound parts. */
  anatomy?: string;
  /** State attribute, styled part and product-agnostic meaning. */
  dataAttributes?: Array<[attribute: string, part: string, meaning: string]>;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}

/**
 * Hook documentation contract. Every hook in `src/hooks/index.ts` has a `hooks/<useName>.doc.ts`
 * exporting `doc: HookDoc`; the registry build, the docs Hooks page and the coverage test read it.
 */
export interface HookDoc {
  /** Public hook name, e.g. "useClipboard". */
  name: string;
  /** Lifecycle badge. */
  status: ComponentDoc['status'];
  description: string;
  /** Call signature, e.g. "useClipboard(options?): { copy, status, copied, error, reset }". */
  signature: string;
  /**
   * What the hook returns without a DOM (server render and first hydration render). Put literal
   * values in backticks: the SSR test checks that the example's server output contains each one.
   */
  server: string;
  /** Non-hook helpers exported next to the hook that this doc covers, e.g. "readLocalStorageValue". Every `use*` hook has its own doc. */
  also?: string[];
}
